mapper.update:
UPDATE product_inventory
SET stock_available=stock_available-#{quantity},stock_sold=stock_sold+#{quantity}
WHERE product_id=#{productId} AND stock_available=#{expectedAvailable}
  AND stock_available>=#{quantity}

mapper.select:
SELECT id FROM inventory_movements
WHERE id=#{movementId} AND product_id=#{productId} AND quantity=#{quantity}
  AND (
    (order_id=#{orderId} AND movement_type IN ('COMMITTED','LATE_PAYMENT_COMMITTED'))
    OR (
      order_id IS NULL AND movement_type='MANUAL_DECREASE'
      AND NOT EXISTS (
        SELECT 1 FROM inventory_reservations
        WHERE order_id=#{orderId} AND product_id=#{productId}
      )
      AND NOT EXISTS (
        SELECT 1 FROM inventory_movements AS existing
        WHERE existing.order_id=#{orderId} AND existing.product_id=#{productId}
      )
    )
  )
FOR UPDATE
